import { describe, expect, it } from 'vitest'
import {
  buildMockInsights,
  defaultConfig,
  getDomainRows,
  getPresets,
} from '../src/components/analysis/analysisDomain'
import { router } from '../src/router'

describe('analysis domain workbench', () => {
  it('reserves default to three-line combo preset config', () => {
    const config = defaultConfig('reserve')
    expect(config.title).toBe('三条线对比')
    expect(config.yAxis).toEqual(['nationalLine', 'internalLine', 'listedLine'])
    expect(config.chartType).toBe('combo')
    expect(getPresets('reserve').some((item) => item.key === 'three-lines')).toBe(true)
  })

  it('planning default covers yearly totals and composition presets', () => {
    const config = defaultConfig('planning')
    expect(config.yAxis).toContain('total2026')
    expect(getPresets('planning').map((item) => item.key)).toEqual(
      expect.arrayContaining(['yearly-total', 'composition', 'by-area']),
    )
    expect(getDomainRows('planning').length).toBeGreaterThan(0)
  })

  it('builds mock insights with version and mock disclaimer', () => {
    const rows = getDomainRows('reserve')
    const insights = buildMockInsights('reserve', rows, defaultConfig('reserve'))
    expect(insights.length).toBeGreaterThanOrEqual(2)
    expect(insights[0].detail).toMatch(/Mock/)
  })

  it('applies three-line preset patch onto config', () => {
    const preset = getPresets('reserve').find((item) => item.key === 'three-lines')!
    const patched = { ...defaultConfig('reserve'), ...preset.apply(), title: '自定义' }
    const after = { ...patched, ...preset.apply() }
    expect(after.title).toBe('三条线对比')
    expect(after.yAxis).toContain('listedLine')
  })
})

describe('planning analysis routing', () => {
  it('redirects legacy /planning/version to analysis version tab', async () => {
    await router.push('/planning/version')
    expect(router.currentRoute.value.path).toBe('/planning/analysis')
    expect(router.currentRoute.value.query.tab).toBe('version')
  })

  it('registers /planning/analysis route', async () => {
    await router.push('/planning/analysis')
    expect(router.currentRoute.value.name).toBe('planning-analysis')
    expect(router.currentRoute.value.meta.title).toBe('统计分析')
  })
})

